Refactor this code by memoizing the exponential recursion:

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

output:
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

What changed: memoization turns exponential recomputation into O(n); the recursion is unchanged, only the decorator was added.

from functools import lru_cache

@lru_cache(maxsize=1)
def template():
    with open('template.html') as f:
        return f.read()

def render(items):
    tpl = template()
    return [tpl.replace('{{name}}', it['name']) for it in items]

What changed: the template is read once and memoized by a zero-argument cache; the loop only does substitution.

from functools import lru_cache

@lru_cache(maxsize=1024)
def role_of(user_id):
    return db.query('SELECT role FROM members WHERE user_id = %s', user_id)

def can_edit(user_id, doc):
    return role_of(user_id) in ('editor', 'admin') and doc['owner'] != user_id

def can_delete(user_id, doc):
    return role_of(user_id) == 'admin'

What changed: one cached role_of() serves every permission check in the request; invalidation happens by clearing role_of.cache_clear() on membership change.

instruction:
Refactor this code by replacing the hand-written dict memo with functools.cache:

def longest_subseq(a, b):
    memo = {}
    def solve(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i == len(a) or j == len(b):
            return 0
        if a[i] == b[j]:
            memo[(i, j)] = 1 + solve(i + 1, j + 1)
        else:
            memo[(i, j)] = max(solve(i + 1, j), solve(i, j + 1))
        return memo[(i, j)]
    return solve(0, 0)

output:
from functools import cache

def longest_subseq(a, b):
    @cache
    def solve(i, j):
        if i == len(a) or j == len(b):
            return 0
        if a[i] == b[j]:
            return 1 + solve(i + 1, j + 1)
        return max(solve(i + 1, j), solve(i, j + 1))
    return solve(0, 0)

What changed: manual memo dict plumbing (lookup, insert, base cases mixed together) became @cache; solve() now reads as pure recurrence.

