Refactor this code by compiling and caching the pattern work per category:

def classify(text):
    rules = {'email': r'[\w.]+@[\w.]+', 'phone': r'\d{3}-\d{4}', 'zip': r'\d{5}'}
    for name, pat in rules.items():
        if re.search(pat, text):
            return name
    return 'unknown'

output:
import re
from functools import lru_cache

PATTERNS = {'email': r'[\w.]+@[\w.]+', 'phone': r'\d{3}-\d{4}', 'zip': r'\d{5}'}

@lru_cache(maxsize=None)
def compiled():
    return {name: re.compile(pat) for name, pat in PATTERNS.items()}

def classify(text):
    for name, pattern in compiled().items():
        if pattern.search(text):
            return name
    return 'unknown'

What changed: rules stay data, but compiled regex objects are built and cached once instead of recompiled per call.

