Refactor this code by adding a caching decorator with logging instead of inline ifs:

def fib(n):
    if n in MEMO:
        return MEMO[n]
    if n < 2:
        return n
    v = fib(n - 1) + fib(n - 2)
    MEMO[n] = v
    return v

MEMO = {}

output:
from functools import wraps

def memoize(fn):
    store = {}
    @wraps(fn)
    def wrapper(n):
        if n not in store:
            store[n] = fn(n)
            logger.debug('miss %s(%s)', fn.__name__, n)
        return store[n]
    return wrapper

@memoize
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

What changed: the global MEMO dict and inline hit/miss branch became a reusable decorator; caching policy is defined once per function.

from decimal import Decimal
from functools import lru_cache

@lru_cache(maxsize=None)
def as_decimal(raw):
    return Decimal(raw)

def render(items):
    return [as_decimal(str(it['amount'])) * Decimal('1.08') for it in items]

What changed: Decimal(str(x)) parsing repeats for the same raw strings; keying a cache by the string makes repeated amounts convert once.

